const R = (n) => $(n).all().map(i => i.json).filter(r => r && Object.keys(r).length);
const L = $now.setZone('Africa/Lagos');
const TODAY = L.toFormat('yyyy-MM-dd');
const ORG = $env.IRIAD_ORGANISATION_ID;
const APP = ($env.APP_BASE_URL || '').replace(/\/$/, '');
const ADMIN_ROLES = ['super_admin', 'admin'];
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const wrap = (title, inner) => `<div style="font-family:Arial,sans-serif;max-width:600px;margin:auto;border:1px solid #e5e7eb"><div style="background:#0f2a4a;color:#fff;padding:16px 20px;font-size:18px;font-weight:bold">IRIAD Operations Portal</div><div style="padding:20px;color:#111827"><h2 style="margin-top:0;font-size:18px">${esc(title)}</h2>${inner}</div><div style="padding:12px 20px;background:#f3f4f6;color:#6b7280;font-size:12px">Automated message from the IRIAD Operations Portal.</div></div>`;
const btn = (href, label) => href ? `<p><a href="${esc(href)}" style="background:#0f2a4a;color:#fff;padding:10px 16px;text-decoration:none;border-radius:4px">${esc(label)}</a></p>` : '';
const rows = [], emails = {}, ids = [];
const add = (p, type, title, text, path, key, inner) => {
  if (!p || !p.id) return;
  rows.push({organisation_id: ORG, recipient_id: p.id, title, body: text, type, link: path, is_read: false, created_at: new Date().toISOString(), dedupe_key: key});
  if (p.email) emails[key] = {to: p.email, subject: title, html: wrap(title, inner || `<p>${esc(text)}</p>` + btn(APP ? APP + path : '', 'Open portal'))};
};
const out = (always) => (rows.length || always) ? [{json: {rows, emails, ids}}] : [];
if (!R('Attendance | Open Session').length) return [];
R('Attendance | Get Active Staff').forEach(p => add(p, 'attendance_opening', 'Check-in is open', 'Morning check-in is open until 9:00 AM. Please check in now.', '/app/attendance', `checkin-open:${TODAY}:${p.id}`));
return out();

const inserted = $('Notification Delivery | Check-in Open Insert Notifications').all().map(i => i.json).filter(r => r && r.dedupe_key);
const emails = $('Attendance | Prepare Open Notices').first().json.emails || {};
return inserted.filter(r => emails[r.dedupe_key]).map(r => ({json: {dedupe_key: r.dedupe_key, to: emails[r.dedupe_key].to, subject: emails[r.dedupe_key].subject, html: emails[r.dedupe_key].html}}));

const built = $('Notification Delivery | Check-in Open Build Emails').all().map(i => i.json);
const res = $input.all().map(i => i.json);
const sent = [], failed = [];
built.forEach((x, i) => { const r = res[i] || {}; (r.id && !r.error ? sent : failed).push(x.dedupe_key); });
const mk = (keys, status) => { const o = []; for (let i = 0; i < keys.length; i += 25) { const k = keys.slice(i, i + 25); o.push({json: {url: `${$env.SUPABASE_URL}/rest/v1/notifications?dedupe_key=in.(${k.map(x => '"' + x + '"').join(',')})`, body: Object.assign({email_status: status}, status === 'sent' ? {email_sent_at: new Date().toISOString()} : {})}}); } return o; };
return [...mk(sent, 'sent'), ...mk(failed, 'failed')];

