const missing = staff.filter(p => !leave.has(p.id) && !field.has(p.id) && !checked.has(p.id));
missing.forEach(p => add(p, 'attendance_reminder', 'Missed check-in', `You have not checked in for ${TODAY}. The window closed at 9:00 AM. If this is wrong, request an attendance correction.`, '/app/attendance', `missing-checkin:${TODAY}:${p.id}`));
if (missing.length) {
  const names = missing.map(p => p.full_name || p.email);
  staff.filter(p => ADMIN_ROLES.includes(p.role)).forEach(a => add(a, 'attendance_summary', `${missing.length} staff missing check-in`, `Missing today: ${names.join(', ')}`, '/app/attendance-control', `missing-checkin-admin:${TODAY}:${a.id}`, `<p>${missing.length} active staff have not checked in (excluding approved leave and field work):</p><ul>${names.map(n => `<li>${esc(n)}</li>`).join('')}</ul>` + btn(APP ? APP + '/app/attendance-control' : '', 'Open attendance control')));
}
return out();

