};
const out = (always) => (rows.length || always) ? [{json: {rows, emails, ids}}] : [];
if (!R('Attendance | Close Sign-out Session').length) return [];   // already closed earlier
const staff = R('Attendance | Get Active Staff (Sign-out Close)');
const byId = new Map(staff.map(p => [p.id, p]));
const inc = R('Attendance | Get Today Attendance (Sign-out)').filter(a => a.check_in_at && !a.check_out_at).map(a => byId.get(a.profile_id)).filter(Boolean);
inc.forEach(p => add(p, 'attendance_signout_missing', 'You have not signed out', `The sign-out window for ${TODAY} has closed and no sign-out was recorded. Please request an attendance correction.`, '/app/attendance', `missing-signout:${TODAY}:${p.id}`));
if (inc.length) {
  const names = inc.map(p => p.full_name || p.email);
  staff.filter(p => ADMIN_ROLES.includes(p.role)).forEach(a => add(a, 'attendance_summary', `${inc.length} incomplete sign-outs`, `Checked in but not signed out: ${names.join(', ')}`, '/app/attendance-control', `missing-signout-admin:${TODAY}:${a.id}`, `<p>${inc.length} staff checked in but did not sign out:</p><ul>${names.map(n => `<li>${esc(n)}</li>`).join('')}</ul>`));
