};
const out = (always) => (rows.length || always) ? [{json: {rows, emails, ids}}] : [];
const staff = R('Leave & Corrections | Get Active Staff');
const byId = new Map(staff.map(p => [p.id, p]));
const admins = staff.filter(p => ADMIN_ROLES.includes(p.role));
const specs = [
  {t: 'leave_requests', who: 'profile_id', label: 'Leave request', pending: 'pending', page: '/app', detail: r => `${r.start_date} to ${r.end_date}`},
  {t: 'attendance_corrections', who: 'profile_id', label: 'Attendance correction', pending: 'pending', page: '/app/attendance', detail: r => r.work_date || r.attendance_date || ''},
  {t: 'weekly_reports', who: 'staff_id', label: 'Weekly report', pending: 'submitted', page: '/app', detail: r => `week of ${r.reporting_week_start}`},
  {t: 'monthly_reports', who: 'staff_id', label: 'Monthly report', pending: 'submitted', page: '/app', detail: r => `month ${r.reporting_month}`}
];
const mark = {};
for (const s of specs) {
  mark[s.t] = {submitted: [], decided: []};
  for (const r of R(`Leave & Corrections | Get ${s.t}`)) {
    const owner = byId.get(r[s.who]);
    const name = owner ? (owner.full_name || owner.email) : 'A staff member';
    const stamp = r.updated_at || r.id;
    if (r.status === s.pending) {
      admins.forEach(a => add(a, `${s.t}_submitted`, `${s.label} submitted`, `${name} submitted a ${s.label.toLowerCase()} (${s.detail(r)}).`, s.page, `${s.t}:${r.id}:submitted:${stamp}:${a.id}`));
      mark[s.t].submitted.push(r.id);
    } else {
      const verb = r.status === 'revision_requested' ? 'needs revision' : r.status;
      add(owner, `${s.t}_${r.status}`, `${s.label} ${verb}`, `Your ${s.label.toLowerCase()} (${s.detail(r)}) ${r.status === 'revision_requested' ? 'needs revision' : 'was ' + r.status}.`, s.page, `${s.t}:${r.id}:${r.status}:${stamp}`);
      mark[s.t].decided.push(r.id);
    }
  }
}
const any = Object.values(mark).some(m => m.submitted.length || m.decided.length);
if (!any) return [];
return [{json: {rows, emails, ids, mark}}];

const mark = $('Leave & Corrections | Prepare Notices').first().json.mark;
const now = new Date().toISOString(); const o = [];
for (const [t, m] of Object.entries(mark)) {
  if (m.submitted.length) o.push({json: {url: `${$env.SUPABASE_URL}/rest/v1/${t}?id=in.(${m.submitted.join(',')})`, body: {submission_notified_at: now}}});
  if (m.decided.length) o.push({json: {url: `${$env.SUPABASE_URL}/rest/v1/${t}?id=in.(${m.decided.join(',')})`, body: {submission_notified_at: now, decision_notified_at: now}}});
}
return o;

